import ast
src = '''
def find(cur, name):
    cur.execute("SELECT * FROM users WHERE name = '" + name + "'")
def find2(cur, name):
    cur.execute(f"SELECT * FROM users WHERE name = '{name}'")
def safe(cur, name):
    cur.execute("SELECT * FROM users WHERE name = %s", (name,))
'''
for node in ast.walk(ast.parse(src)):
    if isinstance(node, ast.Call) and getattr(node.func, "attr", "") == "execute" and node.args:
        a = node.args[0]
        print(f"{node.lineno}행", "의심(CWE-89)" if isinstance(a, (ast.BinOp, ast.JoinedStr)) else "통과(바인딩)")

plan = [
  {"type":"sg_rule","name":"ssh","ports":(22,22),"cidr":["0.0.0.0/0"]},
  {"type":"sg_rule","name":"web","ports":(443,443),"cidr":["0.0.0.0/0"]},
  {"type":"sg_rule","name":"db","ports":(5432,5432),"cidr":["10.0.0.0/16"]},
  {"type":"bucket","name":"logs","encrypted":False}]
ADMIN = {22, 3389, 5432, 3306}
for r in plan:
    if r["type"]=="sg_rule" and "0.0.0.0/0" in r["cidr"] and any(p in ADMIN for p in range(r["ports"][0], r["ports"][1]+1)):
        print("실패", r["name"], "관리 포트가 인터넷 전체에 열림")
    elif r["type"]=="bucket" and not r["encrypted"]:
        print("실패", r["name"], "저장 암호화 꺼짐")
    else:
        print("통과", r["name"])

pod = {"hostNetwork": True, "containers": [
  {"name":"api","image":"app:1.2","sc":{"runAsNonRoot":True,"allowPrivilegeEscalation":False}},
  {"name":"agent","image":"agent:latest","sc":{"privileged":True}}]}
if pod.get("hostNetwork"): print("파드: hostNetwork 사용")
for c in pod["containers"]:
    sc = c["sc"]; bad = []
    if sc.get("privileged"): bad.append("privileged")
    if not sc.get("runAsNonRoot"): bad.append("root 실행 가능")
    if sc.get("allowPrivilegeEscalation", True): bad.append("권한 상승 허용")
    if c["image"].endswith(":latest"): bad.append("latest 태그")
    print(c["name"], "통과" if not bad else "실패: " + ", ".join(bad))
